            } else {
                OriginalCircuitOwnerOutcome::ReturnedErr
            },
            result,
        ),
        Err(error) => (
            OriginalCircuitOwnerOutcome::JoinFailed,
            Err(AgentdError::Protocol(format!(
                "Circuit task owner stopped: {error}"
            ))),
        ),
    };
